    operations.push({
      type: "update",
      id: existingField.id,
      // Added for the GraphQL metafieldsSet call, which upserts by
      // owner+namespace+key rather than needing the metafield's own id.
      owner_id: product.id,
      namespace: "custom",
      key,
      payload: {
        metafield: {
          id: existingField.id,
          value: newValue,
          type: fieldType
        }
      }
    });
  }
}

